  '준비가 끝나면 **최후의 공세**가 3차에 걸쳐 온다. **B**를 누르면 기다리지 않고 지금 연다',
  '한 번 막아내면 승리 확정. 거기서 **[계속하기]**를 누르면 라운드마다 더 세지고 버틴 시간이 기록된다',
